document.addEventListener("DOMContentLoaded", () => {
    const widthScreen = window.innerWidth || document.documentElement.clientWidth ||
        document.body.clientWidth;


    function getScrollMenu() {
        let el = document.body;
        if (pageYOffset > 100) {
            el.classList.add('fix_menu');
        } else {
            el.classList.remove("fix_menu");
        }
    }

    getScrollMenu();
    window.addEventListener('scroll', function () {
        getScrollMenu();
    });

    if (document.getElementById('sliderNews')) {
        const sliderBrands = new Swiper('#sliderNews', {
            spaceBetween: 24,
            slidesPerView: 3,
            slidesPerGroup: 1,

            breakpoints: {
                300: {
                    slidesPerView: 'auto',
                    spaceBetween: 16
                },
                768: {
                    slidesPerView: 'auto',
                    spaceBetween: 24
                },
                991: {
                    slidesPerView: 3,
                    spaceBetween: 24
                },
                1200: {
                    slidesPerView: 3,
                    spaceBetween: 24
                },
            },

        });
    }

    if (document.getElementById('sliderReg')) {
        let sliderReg = new Swiper('#sliderReg', {
            effect: "fade",
            crossFade: true,
            speed: 1000,
            observer: true,
            observeParents: true,
            autoplay: {
                delay: 3000,
                disableOnInteraction: false,
            },
        });
    }

    if (document.getElementById('authModal')) {
        const authModal = document.getElementById('authModal')
        authModal.addEventListener('show.bs.modal', event => {
            const button = event.relatedTarget;
            if (button) {
                const targetTab = button.getAttribute('data-bs-tab');
                if (targetTab) {
                    const tabElement = document.querySelector(`#${targetTab}-tab`);
                    if (tabElement) {
                        tabElement.click();
                    }
                }
            }
        })
    }


    const jsPass = document.querySelectorAll('.js-pass');

    jsPass.forEach(el => {
        el.addEventListener('click', (event) => {
            if (document.getElementById(el.dataset.target)) {
                let inputPass = document.getElementById(el.dataset.target);
                if (inputPass.type === 'password') {
                    inputPass.type = 'text';
                    el.classList.add('active');
                } else {
                    inputPass.type = 'password';
                    el.classList.remove('active');
                }
            }
            event.preventDefault(false);
        });
    });

    if (document.getElementById('formReg')) {
        let form = document.getElementById('formReg');
        const submitBtn = document.getElementById('submitBtn');

        const validator = new JustValidate('#formReg', {
            errorFieldCssClass: 'is-invalid',
            successFieldCssClass: 'is-valid',
            validateBeforeSubmitting: true,
        });

        if (document.getElementById('email')) {
            validator.addField('#email', [
                {
                    rule: 'required',
                    errorMessage: 'Введите email',
                },
                {
                    rule: 'email',
                    errorMessage: 'Введите корректный email',
                },
            ]);
        }

        if (document.getElementById('pass')) {
            validator.addField('#pass', [
                {
                    rule: 'required',
                    errorMessage: 'Введите пароль',
                },
                { rule: 'minLength', value: 6, errorMessage: 'Пароль должен быть не менее 6 символов длиной' }
            ]);
        }

        if (document.getElementById('pass2')) {
            validator.addField('#pass2', [
                {
                    rule: 'required',
                    errorMessage: 'Введите пароль',
                },
                {
                    validator: (value, fields) => {
                        return value === fields['#pass'].elem.value;
                    },
                    errorMessage: 'Пароли не совпадают',
                }
            ]);
        }

        if (document.getElementById('capcha')) {
            validator.addField('#capcha', [
                {
                    rule: 'required',
                    errorMessage: 'Введите слово с картинки',
                }
            ]);
        }

        const checkbox = form.querySelector('input[name="save"]');
        if (checkbox) {
            validator.addField(checkbox, [
                { rule: 'required', errorMessage: 'Необходимо согласие' }
            ]);
        }

        // Проверка состояния формы
        const checkFormValidity = () => {
            //console.log('1111');
            const isValid = form.checkValidity();
            submitBtn.disabled = !isValid;
        };

        // Обновление состояния кнопки при изменении в полях формы
        const fields = form.querySelectorAll('input, textarea');
        fields.forEach((field) => {
            field.addEventListener('input', checkFormValidity);
        });

        // Начальная проверка состояния кнопки
        checkFormValidity();

        form.addEventListener('submit', function (e) {
            e.preventDefault();
            validator.revalidate().then(isValid => {
                if (isValid) {
                    // Создаём скрытую кнопку, чтобы Битрикс обработал форму
                    let hiddenBtn = form.querySelector('input[name="register_submit_button"][type="hidden"]');
                    if (!hiddenBtn) {
                        hiddenBtn = document.createElement('input');
                        hiddenBtn.type = 'hidden';
                        hiddenBtn.name = 'register_submit_button';
                        hiddenBtn.value = 'Регистрация';
                        form.appendChild(hiddenBtn);
                    }

                    HTMLFormElement.prototype.submit.call(form);
                }
            });
        });
    }

    /*if(location.hash){
        const triggerEl = document.querySelector(location.hash)
        bootstrap.Tab.getOrCreateInstance(triggerEl).show()
    }

    const selectableTabList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tab"]'))
    selectableTabList.forEach((selectableTab) => {
        selectableTab.addEventListener('shown.bs.tab', event => {
            console.log('Previous URL: ' + location.href);
            history.replaceState(null, null, '#' + event.target.id);
        })
    });*/

    if (document.getElementById('revSlider')) {
        const sliderBrands = new Swiper('#revSlider', {
            spaceBetween: 24,
            slidesPerView: 3,
            slidesPerGroup: 1,
            navigation: {
                nextEl: '#revNext',
                prevEl: '#revPrev',
            },

            /* pagination: {
                 el: '#historySliderPagination',
                 clickable: true,
             },*/

            breakpoints: {
                300: {
                    slidesPerView: 'auto',
                    spaceBetween: 16
                },
                769: {
                    slidesPerView: 2,
                    spaceBetween: 24
                },
                991: {
                    slidesPerView: 3,
                    spaceBetween: 24
                },
                1200: {
                    slidesPerView: 3,
                    spaceBetween: 24
                },
            },

        });
    }

    if (document.getElementById('specProjects')) {
        if (widthScreen > 768) {
            const specProjects = new Swiper('#specProjects', {
                spaceBetween: 24,
                slidesPerView: 2,
                slidesPerGroup: 1,

                navigation: {
                    nextEl: '#specProjectsNext',
                    prevEl: '#specProjectsPrev',
                },


                breakpoints: {
                    300: {
                        slidesPerView: 1,
                        enabled: true
                    },
                    768: {
                        slidesPerView: 1,
                        enabled: true
                    },
                    991: {
                        slidesPerView: 2,
                        spaceBetween: 24
                    },
                    1200: {
                        slidesPerView: 2,
                        spaceBetween: 24
                    },
                },

            });
        }

        if (widthScreen <= 768 && specProjects) {
            specProjects.destroy(true, true);
            specProjects = null;
        }
    }
    if (document.getElementById('historySlider')) {
        const sliderBrands = new Swiper('#historySlider', {
            spaceBetween: 24,
            slidesPerView: 3,
            slidesPerGroup: 1,
            navigation: {
                nextEl: '#historySliderNext',
                prevEl: '#historySliderPrev',
            },

            breakpoints: {
                300: {
                    slidesPerView: 'auto',
                    spaceBetween: 16
                },
                769: {
                    slidesPerView: 2,
                    spaceBetween: 24
                },
                991: {
                    slidesPerView: 3,
                    spaceBetween: 24
                },
                1200: {
                    slidesPerView: 3,
                    spaceBetween: 24
                },
            },

        });
    }

    if (document.getElementById('cabinetTabs')) {
        new Swiper('#cabinetTabs', {
            spaceBetween: 40,
            slidesPerView: 'auto',
            breakpoints: {
                300: {

                    spaceBetween: 16
                },
                769: {
                    spaceBetween: 24
                },
                991: {
                    spaceBetween: 40
                },
                1200: {
                    spaceBetween: 40
                },
            },

        });
    }

    if (document.getElementById('filterLetter')) {
        new Swiper('#filterLetter', {
            spaceBetween: 5,
            slidesPerView: 'auto',
        });
    }
    if (document.getElementById('variantsFilter')) {
        new Swiper('#variantsFilter', {
            spaceBetween: 10,
            slidesPerView: 'auto',
        });
    }

    let sliderNews = document.querySelectorAll(".js-slider");

    sliderNews.forEach(function (sliderItem) {
        let pageBtn = '#' + sliderItem.dataset.page;
        let nextBtn = '#' + sliderItem.dataset.next;
        let prevBtn = '#' + sliderItem.dataset.prev;

        new Swiper(sliderItem, {
            loop: true,
            spaceBetween: 30,
            effect: "fade",
            pagination: {
                el: pageBtn,
                clickable: true,
            },
            navigation: {
                nextEl: nextBtn,
                prevEl: prevBtn,
            },
        });
    });

    let sliderJournal = document.querySelectorAll(".js-slider-journal");

    sliderJournal.forEach(function (sliderItem) {
        let nextBtn = '#' + sliderItem.dataset.next;
        let prevBtn = '#' + sliderItem.dataset.prev;

        new Swiper(sliderItem, {
            spaceBetween: 24,
            slidesPerView: 3,
            slidesPerGroup: 1,
            navigation: {
                nextEl: nextBtn,
                prevEl: prevBtn,
            },
            breakpoints: {
                300: {
                    slidesPerView: 'auto',
                    spaceBetween: 16
                },
                768: {
                    slidesPerView: 'auto',
                    spaceBetween: 24
                },
                991: {
                    slidesPerView: 3,
                    spaceBetween: 24
                },
                1200: {
                    slidesPerView: 3,
                    spaceBetween: 24
                },
            },

        });
    });
    if (document.getElementById('chem_elements_slider')) {
        if (widthScreen < 991) {
            new Swiper('#chem_elements_slider', {
                spaceBetween: 10,
                slidesPerView: 'auto',
                slidesPerGroup: 1,

            });
        }
    }

    if (document.getElementById('booksSlider')) {
        const sliderBrands = new Swiper('#booksSlider', {
            spaceBetween: 24,
            slidesPerView: 4,
            slidesPerGroup: 1,
            navigation: {
                nextEl: '#booksSliderNext',
                prevEl: '#booksSliderPrev',
            },

            breakpoints: {
                300: {
                    slidesPerView: 'auto',
                    spaceBetween: 16
                },
                769: {
                    slidesPerView: 2,
                    spaceBetween: 24
                },
                991: {
                    slidesPerView: 3,
                    spaceBetween: 24
                },
                1200: {
                    slidesPerView: 4,
                    spaceBetween: 24
                },
            },

        });
    }


    if (document.getElementById('yearsFilter')) {
        if (widthScreen > 991) {
            const accYears = document.getElementById('accYears');

            const yearsFilter = document.getElementById('yearsFilter');
            const yearsSlider = document.getElementById('yearsSlider');
            const years = document.getElementById('years');
            let yearItems = yearsFilter.querySelectorAll('.header-filter__years-list__item');

            accYears.addEventListener('hidden.bs.collapse', event => {
                yearsFilter.classList.remove('active');
            });
            accYears.addEventListener('show.bs.collapse', event => {
                yearsFilter.classList.add('active');
            });

            const lastSlideIndex = yearsSlider.querySelectorAll('.swiper-slide').length - 1;

            new Swiper('#yearsSlider', {
                initialSlide: lastSlideIndex,
                slidesPerView: 1,
                spaceBetween: 20,
                navigation: {
                    nextEl: '#yearsSliderNext',
                    prevEl: '#yearsSliderPrev',
                },
            });

            yearItems.forEach(function (year) {
                year.addEventListener('click', () => {
                    document.querySelector('.header-filter__years-list__item.active').classList.remove('active');
                    year.classList.add('active');
                    years.innerHTML = parseInt(year.innerHTML);
                    bootstrap.Collapse.getOrCreateInstance(accYears).hide();
                });
            });


            const accYears2 = document.getElementById('accYears2');

            const yearsFilter2 = document.getElementById('yearsFilter2');
            const yearsSlider2 = document.getElementById('yearsSlider2');
            const years2 = document.getElementById('years2');
            let yearItems2 = yearsFilter2.querySelectorAll('.header-filter__years-list__item');

            accYears2.addEventListener('hidden.bs.collapse', event => {
                yearsFilter2.classList.remove('active');
            });
            accYears2.addEventListener('show.bs.collapse', event => {
                yearsFilter2.classList.add('active');
            });

            const lastSlideIndex2 = yearsSlider2.querySelectorAll('.swiper-slide').length - 1;

            new Swiper('#yearsSlider2', {
                initialSlide: lastSlideIndex2,
                slidesPerView: 1,
                spaceBetween: 20,
                navigation: {
                    nextEl: '#yearsSliderNext2',
                    prevEl: '#yearsSliderPrev2',
                },
            });

            yearItems2.forEach(function (year2) {
                year2.addEventListener('click', () => {
                    yearsFilter2.querySelector('.header-filter__years-list__item.active').classList.remove('active');
                    year2.classList.add('active');
                    years2.innerHTML = parseInt(year2.innerHTML);
                    bootstrap.Collapse.getOrCreateInstance(accYears2).hide();
                });
            });
        } else {
            new Swiper('#mobSliderYears', {
                slidesPerView: 1,
                spaceBetween: 20,
            });

            let yearItems = document.querySelectorAll('.modal__filter-years__item');
            const yearsMob = document.getElementById('yearsMob');

            yearItems.forEach(function (year) {
                year.addEventListener('click', () => {
                    document.querySelector('.modal__filter-years__item.active').classList.remove('active');
                    year.classList.add('active');
                    yearsMob.value = parseInt(year.innerHTML);
                });
            });
        }
    }

    if (widthScreen > 991 && document.querySelector('.js-sidebar')) {
        var sidebar = new StickySidebar('.js-sidebar', {
            topSpacing: 80,
            bottomSpacing: 20,
            containerSelector: '.js-main-content',
            innerWrapperSelector: '.marketing-sb'
        });
    }


    const btn = document.querySelector('.scroll-top');
    const footer = document.querySelector('юfooter');
    const firstScreenHeight = () => window.innerHeight;
    const OFFSET = 24; // gap from bottom/footer

    function update() {
        const scrollY = window.scrollY || window.pageYOffset;
        const vh = window.innerHeight;
        const docHeight = document.documentElement.scrollHeight;

        // Visibility
        if (scrollY > vh - 50) {
            btn.classList.add('is-visible');
        } else {
            btn.classList.remove('is-visible');
        }

        // Footer collision
        if (footer) {
            const footerRect = footer.getBoundingClientRect();
            const footerVisible = vh - footerRect.top;
            if (footerVisible > 0) {
                btn.style.bottom = (footerVisible + OFFSET) + 'px';
            } else {
                btn.style.bottom = OFFSET + 'px';
            }
        }
    }

    window.addEventListener('scroll', update, { passive: true });
    window.addEventListener('resize', update);

    btn.addEventListener('click', () => {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    });

    update();
});
